    41	  launch(body: unknown): Response {
    42	    const b = (body ?? {}) as { name?: string; command?: string };
    43	    try {
    44	      return { status: 201, body: { id: this.launcher.launch(b.name ?? "", b.command ?? "") } };
    45	    } catch (e) {
    46	      return { status: 400, body: { error: (e as Error).message } };
    47	    }
    48	  }
    49	
    50	  /** Events forwarded by remote runners (other hosts). They arrive in whatever order the network delivers. */
    51	  ingest(body: unknown): Response {
    52	    const events = Array.isArray(body) ? body : [body];
    53	    let accepted = 0;
    54	    for (const e of events) {
    55	      if (!isJobEvent(e)) continue;
    56	      this.projection.apply(e);
    57	      accepted++;
    58	    }
    59	    return { status: 202, body: { accepted } };
    60	  }
