    24	export function createConsole(spawn: (command: string, now: () => number) => ProcessHandle, overrides: Partial<ConsoleConfig> = {}): ConsoleApp {
    25	  const config: ConsoleConfig = { ...defaultConfig, ...overrides };
    26	  const clock = new ManualClock();
    27	  const bus = new EventBus<JobEvent>();
    28	  const store = new JobViewStore();
    29	  const projection = new JobProjection(store);
    30	  bus.subscribe((e) => projection.apply(e));
    31	  const supervisor = new Supervisor(bus, clock, config);
    32	  const factory: ProcessFactory = (command) => spawn(command, () => clock.now());
    33	  const launcher = new Launcher(supervisor, factory);
    34	  const retention = new RetentionService(store, clock, config.retainFinishedMs);
    35	  const router = new Router(new JobsHandler(store, launcher, projection, config));
    36	
    37	  const tick = () => {
    38	    clock.advance(config.tickMs);
    39	    supervisor.tick();
    40	    bus.drain();
    41	    retention.sweep();
    42	  };
    43	  return {
    44	    router,
    45	    clock,
    46	    tick,
    47	    runFor(ms: number) {
    48	      const end = clock.now() + ms;
    49	      while (clock.now() < end) tick();
    50	    },
    51	    activeJobs: () => supervisor.activeJobs(),
    52	  };
    53	}
