     5	/** Folds job events into the read model the console API serves. */
     6	export class JobProjection {
     7	  constructor(private readonly store: JobViewStore) {}
     8	
     9	  apply(e: JobEvent): void {
    10	    switch (e.kind) {
    11	      case "started":
    12	        this.store.put({
    13	          id: e.jobId,
    14	          name: e.name,
    15	          status: "running",
    16	          exitCode: null,
    17	          log: [],
    18	          seq: 0,
    19	          startedAt: e.at,
    20	          endedAt: null,
    21	        });
    22	        return;
    23	      case "timeline": {
    24	        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
    25	        if (e.seq <= view.seq) return; // stale snapshot
    26	        this.store.put({ ...view, status: "running", log: e.lines, seq: e.seq });
    27	        return;
    28	      }
    29	      case "closed": {
    30	        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
    31	        this.store.put({ ...view, status: statusForExit(e.exitCode), exitCode: e.exitCode, endedAt: e.at });
    32	        return;
    33	      }
    34	    }
    35	  }
    36	
    37	  private blank(id: string): JobView {
    38	    return { id, name: id, status: "running", exitCode: null, log: [], seq: 0, startedAt: 0, endedAt: null };
    39	  }
    40	}
