     1	/** What the console can observe about a running child process. */
     2	export interface ProcessHandle {
     3	  /** Raw output chunks written so far (may contain ANSI escapes and \r). */
     4	  output(): string[];
     5	  /** Exit code once the process has exited, otherwise null. */
     6	  exitCode(): number | null;
     7	}
     8	
     9	export interface ScriptStep {
    10	  /** Milliseconds after the process was started. */
    11	  at: number;
    12	  write?: string;
    13	  exit?: number;
    14	}
    15	
    16	/** Deterministic stand-in for a child process, driven by the console clock. */
    17	export class ScriptedProcess implements ProcessHandle {
    18	  private readonly startedAt: number;
    19	
    20	  constructor(private readonly steps: ScriptStep[], private readonly now: () => number) {
    21	    this.startedAt = now();
    22	  }
    23	
    24	  output(): string[] {
    25	    const t = this.now() - this.startedAt;
    26	    return this.steps.filter((s) => s.at <= t && s.write !== undefined).map((s) => s.write as string);
    27	  }
    28	
    29	  exitCode(): number | null {
    30	    const t = this.now() - this.startedAt;
    31	    const exit = this.steps.find((s) => s.exit !== undefined && s.at <= t);
    32	    return exit ? (exit.exit as number) : null;
    33	  }
    34	}
