     7	
     8	/**
     9	 * Polls one job's output every tick and publishes log snapshots.
    10	 * Snapshots are coalesced: at most one per `emitMinIntervalMs`; a change that
    11	 * arrives inside the window goes out with the first tick after it.
    12	 */
    13	export class LogPump {
    14	  private lastFp: string | null = null;
    15	  private unsent: string[] | null = null;
    16	  private lastEmit = Number.NEGATIVE_INFINITY;
    17	  private seq = 0;
    18	  private stopped = false;
    19	
    20	  constructor(
    21	    private readonly jobId: string,
    22	    private readonly tail: OutputTail,
    23	    private readonly bus: EventBus<JobEvent>,
    24	    private readonly clock: Clock,
    25	    private readonly config: ConsoleConfig,
    26	  ) {}
    27	
    28	  tick(): void {
    29	    if (this.stopped) return;
    30	    const lines = this.tail.read();
    31	    const fp = fingerprint(lines);
    32	    if (fp !== this.lastFp) {
    33	      this.lastFp = fp;
    34	      this.unsent = lines;
    35	    }
    36	    const now = this.clock.now();
    37	    if (this.unsent !== null && now - this.lastEmit >= this.config.emitMinIntervalMs) {
    38	      this.bus.publish("data", { kind: "timeline", jobId: this.jobId, seq: ++this.seq, lines: this.unsent });
    39	      this.unsent = null;
    40	      this.lastEmit = now;
    41	    }
    42	  }
    43	
    44	  stop(): void {
    45	    this.stopped = true;
    46	  }
    47	
    48	  sent(): number {
    49	    return this.seq;
    50	  }
