    14	
    15	/** Owns the per-job pump and exit watcher; driven by the host loop. */
    16	export class Supervisor {
    17	  private readonly running = new Map<string, Running>();
    18	
    19	  constructor(
    20	    private readonly bus: EventBus<JobEvent>,
    21	    private readonly clock: Clock,
    22	    private readonly config: ConsoleConfig,
    23	  ) {}
    24	
    25	  attach(jobId: string, name: string, proc: ProcessHandle): void {
    26	    if (this.running.has(jobId)) throw new Error(`job ${jobId} already attached`);
    27	    const pump = new LogPump(jobId, new OutputTail(proc), this.bus, this.clock, this.config);
    28	    const watcher = new ExitWatcher(jobId, proc, this.bus, this.clock, () => this.detach(jobId));
    29	    this.running.set(jobId, { pump, watcher });
    30	    this.bus.publish("control", { kind: "started", jobId, name, at: this.clock.now() });
    31	  }
    32	
    33	  tick(): void {
    34	    for (const { pump, watcher } of [...this.running.values()]) {
    35	      pump.tick();
    36	      watcher.tick();
    37	    }
    38	  }
