     1	/**
     2	 * In-process message bus shared with other services.
     3	 *
     4	 * Two lanes: "control" for small lifecycle messages and "data" for bulk payloads.
     5	 * Each lane is FIFO. On drain, control messages are delivered before data so that
     6	 * lifecycle changes are never stuck behind large payloads. No ordering is promised
     7	 * between the two lanes.
     8	 */
     9	export type Lane = "control" | "data";
    10	
    11	export type Subscriber<T> = (msg: T) => void;
    12	
    13	export class EventBus<T> {
    14	  private readonly queues: Record<Lane, T[]> = { control: [], data: [] };
    15	  private readonly subscribers: Subscriber<T>[] = [];
    16	  private delivered = 0;
    17	
    18	  publish(lane: Lane, msg: T): void {
    19	    this.queues[lane].push(msg);
    20	  }
    21	
    22	  subscribe(fn: Subscriber<T>): () => void {
    23	    this.subscribers.push(fn);
    24	    return () => {
    25	      const i = this.subscribers.indexOf(fn);
    26	      if (i >= 0) this.subscribers.splice(i, 1);
    27	    };
    28	  }
    29	
    30	  /** Delivers everything queued so far. Messages published during delivery wait for the next drain. */
    31	  drain(): number {
    32	    const batch = [...this.queues.control, ...this.queues.data];
    33	    this.queues.control = [];
    34	    this.queues.data = [];
    35	    for (const msg of batch) {
    36	      for (const s of [...this.subscribers]) s(msg);
    37	    }
    38	    this.delivered += batch.length;
    39	    return batch.length;
    40	  }
    41	
    42	  pending(): number {
    43	    return this.queues.control.length + this.queues.data.length;
    44	  }
    45	
    46	  stats(): { delivered: number } {
    47	    return { delivered: this.delivered };
    48	  }
    49	}
