     1	/** Cheap change detector for a list of lines (FNV-1a over content + count). */
     2	export function fingerprint(lines: readonly string[]): string {
     3	  let h = 0x811c9dc5;
     4	  for (const line of lines) {
     5	    for (let i = 0; i < line.length; i++) {
     6	      h ^= line.charCodeAt(i);
     7	      h = Math.imul(h, 0x01000193);
     8	    }
     9	    h ^= 0x0a;
    10	    h = Math.imul(h, 0x01000193);
    11	  }
    12	  return `${lines.length}:${(h >>> 0).toString(16)}`;
    13	}

