// Events can arrive out of order (remote runners, two bus lanes), so none of them may move a job
// backwards: "started" keeps existing log/seq/status, timeline never touches status, and the first "closed" is final.
case "started": {
  const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
